import{loadP0LightingAdapter}from'./lighting-adapter.mjs';
import{PROLOGUE_RIVAL as RIVAL}from'../prologue-rival/fixed-registration.mjs';
import{clearRival}from'../prologue-rival/geometry.mjs';
import{loadPrologueVisualLayer}from'./visual-layer.mjs';
import{PROLOGUE_SCENE as R,PROLOGUE_PREVIOUS_SCENE as OLD}from'./scene.mjs';
import{loadSelectedPlayerFrames}from'../gohyeon-pair/player_frames/load-player-frames.mjs';
import{selectPlayerFrame}from'../gohyeon-pair/player-frame.mjs';
const moduleURL=import.meta.url,keys=['sceneId','mapId','revision','imageSHA','maskSHA','foot','facing'];
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const footValue=f=>{if(!Array.isArray(f)||Object.getPrototypeOf(f)!==Array.prototype||Reflect.ownKeys(f).length!==3)return null;const d=[0,1].map(i=>Object.getOwnPropertyDescriptor(f,String(i)));return d.every(x=>x&&Object.hasOwn(x,'value')&&x.enumerable&&Number.isSafeInteger(x.value))?d.map(x=>x.value):null};
/** Pure pinned presentation; owner alone stores foot and commits original recovery draft. */
export async function preparePrologue({signal,fetcher=fetch,canvasFactory,decode=async b=>createImageBitmap(new Blob([b]))}={}){
 const cleanupErrors=[];let disposed=false,actors=null,image=null,visual=null,rival=null,lighting=null;const check=()=>{if(disposed||signal?.aborted)throw Error('PROLOGUE_PREPARE_CANCELLED')};
 const close=()=>{if(disposed)return;disposed=true;const list=[lighting,image,rival,actors,visual];lighting=image=rival=actors=visual=null;for(const r of list)try{if(typeof r?.close==='function')r.close();else r?.dispose?.()}catch(e){cleanupErrors.push(e)}};
 const read=async url=>{check();const r=await fetcher(url,{signal});if(!r.ok)throw Error('PROLOGUE_INPUT_MISSING');const raw=await r.arrayBuffer(),b=new Uint8Array(raw instanceof ArrayBuffer?raw.slice(0):raw);check();return b};
 const decodeOwned=async b=>{check();const value=await decode(b);if(disposed||signal?.aborted){try{value.close?.()}catch(e){cleanupErrors.push(e)}throw Error('PROLOGUE_PREPARE_CANCELLED')}return value};
 try{const[art,mask,oldMask]=await Promise.all([read(new URL('./assets/prologue.png',moduleURL)),read(new URL('./assets/main-junction-r3.safe.u8',moduleURL)),read(new URL('./assets/main.safe.u8',moduleURL))]);if(await hash(art)!==R.imageSHA||await hash(mask)!==R.maskSHA||mask.length!==R.width*R.height||oldMask.length!==R.width*R.height||await hash(oldMask)!==OLD.maskSHA)throw Error('PROLOGUE_PIN_MISMATCH');check();
 actors=await loadSelectedPlayerFrames({fetcher:async url=>{const b=await read(url);return{ok:true,arrayBuffer:async()=>b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength)}},decode:decodeOwned});image=await decodeOwned(art);check();if(image.width!==R.width||image.height!==R.height)throw Error('PROLOGUE_IMAGE_SIZE');visual=await loadPrologueVisualLayer({fetcher,decode:decodeOwned,signal,canvasFactory});check();
 const rivalBytes=await read(new URL('../../assets/approved-atlases/npc/HARIN.png',moduleURL));if(await hash(rivalBytes)!==RIVAL.atlas.sha256)throw Error('PROLOGUE_RIVAL_ATLAS_PIN');rival=await decodeOwned(rivalBytes);if(rival.width!==480||rival.height!==784)throw Error('PROLOGUE_RIVAL_ATLAS_SIZE');lighting=await loadP0LightingAdapter({fetcher,signal,image,visual,canvasFactory});check();
 const safe=foot=>{const f=footValue(foot);return!disposed&&!!f&&f[0]>=0&&f[1]>=0&&f[0]<R.width&&f[1]<R.height&&mask[f[1]*R.width+f[0]]===1&&clearRival(f)};
 const validate=n=>{if(disposed)return'PROLOGUE_PRESENTATION_DISPOSED';if(!n||Object.getPrototypeOf(n)!==Object.prototype||Reflect.ownKeys(n).length!==keys.length||keys.some(k=>{const d=Object.getOwnPropertyDescriptor(n,k);return!d||!Object.hasOwn(d,'value')||!d.enumerable}))return'INVALID_PROLOGUE_LOCATION';if(n.sceneId!==R.sceneId||n.mapId!==R.mapId||n.revision!==R.revision||n.imageSHA!==R.imageSHA||n.maskSHA!==R.maskSHA)return'PROLOGUE_LOCATION_PIN_MISMATCH';if(!['up','down','left','right'].includes(n.facing)||!safe(n.foot))return'UNSUPPORTED_PROLOGUE_POSE';return true};
 const validatePrevious=n=>{if(disposed)return'PROLOGUE_PRESENTATION_DISPOSED';if(!n||Object.getPrototypeOf(n)!==Object.prototype||Reflect.ownKeys(n).length!==keys.length||keys.some(k=>{const d=Object.getOwnPropertyDescriptor(n,k);return!d||!Object.hasOwn(d,'value')||!d.enumerable}))return'INVALID_PREVIOUS_PROLOGUE_LOCATION';if(['sceneId','mapId','revision','imageSHA','maskSHA'].some(k=>n[k]!==OLD[k]))return'PREVIOUS_PROLOGUE_PIN_MISMATCH';const f=footValue(n.foot);return f&&f[0]>=0&&f[1]>=0&&f[0]<R.width&&f[1]<R.height&&oldMask[f[1]*R.width+f[0]]===1&&['up','down','left','right'].includes(n.facing)?true:'PREVIOUS_PROLOGUE_POSE_UNSUPPORTED'};
 const migratePrevious=n=>{if(validatePrevious(n)!==true)throw Error('PREVIOUS_PROLOGUE_LOCATION_INVALID');if(!safe(n.foot))throw Error('PREVIOUS_PROLOGUE_SAME_FOOT_HOLD');return Object.freeze({sceneId:R.sceneId,mapId:R.mapId,revision:R.revision,imageSHA:R.imageSHA,maskSHA:R.maskSHA,foot:Object.freeze([...n.foot]),facing:n.facing})};
 return Object.freeze({pinsVerified:true,lampRegistration:visual.junctionRegistration,safe,validate,validatePrevious,migratePrevious,draw(ctx,{foot,facing,elapsedMs=0,moving=false,minutes=720,lights=true,rest=false}){if(!safe(foot)||!['up','down','left','right'].includes(facing))throw Error('UNSUPPORTED_PROLOGUE_POSE');const[x,y]=foot,w=ctx.canvas.width,h=ctx.canvas.height,cx=Math.max(0,Math.min(R.width-w,x-w/2)),cy=Math.max(0,Math.min(R.height-h,y-h/2));ctx.save();try{ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,w,h);ctx.drawImage(image,cx,cy,w,h,0,0,w,h);visual.draw(ctx,{offsetX:cx,offsetY:cy,elapsedMs});const frame=selectPlayerFrame({facing,walking:moving,elapsedMs}),drawRival=g=>{const f=RIVAL.frame,s=5/12;g.drawImage(rival,...f.rect,RIVAL.npcFoot[0]-cx-f.anchor[0]*s,RIVAL.npcFoot[1]-cy-f.anchor[1]*s,f.width*s,f.height*s)};lighting.compose(ctx,{camera:[cx,cy],minutes,lights,rest,actors:[{y:RIVAL.npcFoot[1],bounds:[RIVAL.npcFoot[0]-cx-RIVAL.frame.anchor[0]*5/12,RIVAL.npcFoot[1]-cy-RIVAL.frame.anchor[1]*5/12,RIVAL.frame.width*5/12,RIVAL.frame.height*5/12],draw:drawRival},{y,bounds:[x-cx-53,y-cy-90,107,107],draw:g=>g.drawImage(actors.actors['actor:'+frame],x-cx-53,y-cy-90)}]});}finally{ctx.restore()}},dispose:close,get cleanupErrors(){return[...cleanupErrors]}});
 }catch(e){close();throw e}
}
